import{z as E,x as p,o as t,c as B,q as s,j as i,D as r,d as l,s as n,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Kafka 日志","description":"","frontmatter":{"title":"Kafka 日志","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kafka-log.md","filePath":"cs/kafka-log.md","lastUpdated":1791413859000}'),f={name:"cs/kafka-log.md"};function A(c,a,k,m,D,S){const o=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=s('<h1 id="kafka-日志" tabindex="-1">Kafka 日志 <a class="header-anchor" href="#kafka-日志" aria-label="Permalink to &quot;Kafka 日志&quot;">​</a></h1><div class="epigraph"><p>分区是有序、只追加、可多消费者重放的提交日志。ISR 与高水位决定「提交」；位移是消费者的游标，不是全局事务。</p><footer>—— 据 Kreps, Narkhede and Rao, Kafka: a Distributed Messaging System for Log Processing, 2011；Apache Kafka 复制设计整理</footer></div><p>上一课<a href="/cs/saga-pattern">Saga</a>需要事件序与可重放。缺口是<strong>日志作为系统总线</strong>：不是队列「拿走即删」，而是保留、重放、多订阅。本课钉分区日志与副本，不重写补偿。后课 pub-sub 是更一般的模式，Kafka 是一种实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每个 topic 分多个 partition，每分区总序，跨分区无全序——这是吞吐换序。生产者按键哈希进分区。副本：leader + ISR 跟随者。<code>acks=all</code> 等到 ISR 持久才认为提交。高水位：所有 ISR 都有的偏移，消费者只能读到这里，防止读未提交再因领导者切换消失。</p><p><span class="marginnote">术语翻译：ISR（in-sync replicas，同步副本集）就是「紧跟 leader 进度」的副本名单。<code>acks=all</code> 等的 all 指这份名单，不是全集群所有副本——掉队者会被移出名单，提交门槛随之变化。</span></p><p>缺口：把 Kafka 当 RSM。它复制的是字节日志，不确定性 apply 你的 \\(\\delta\\)。恰好一次是生产者 id + 事务标记的限定功能，不是任意消费者副作用。</p><p><span class="marginnote">2011 笔记把日志当 Kafka 核心抽象。后续事务、KRaft 去 ZK 是工程演进，本课以日志+ISR 为对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>消费组：一分区同一组内一个消费者，位移提交到内部 topic。重平衡使位移与所有权抖动，重复投递窗口回来——接<a href="/cs/delivery-semantics">投递语义</a>。保留策略按时间或大小截断，截断后不能当归档真理除非另备。</p>',10)),(t(),i(d,null,{default:r(()=>[n(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E7%94%9F%E4%BA%A7%E8%80%85%22%5D%20--%3E%20L%5B%22%E5%88%86%E5%8C%BA%20leader%22%5D%0A%20%20L%20--%3E%20ISR%5B%22ISR%20%E5%A4%8D%E5%88%B6%22%5D%0A%20%20ISR%20--%3E%20HW%5B%22%E9%AB%98%E6%B0%B4%E4%BD%8D%20%3D%20%E6%8F%90%E4%BA%A4%22%5D%0A%20%20HW%20--%3E%20CS%5B%22%E6%B6%88%E8%B4%B9%E8%80%85%E4%BD%8D%E7%A7%BB%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与链式复制：ISR 是动态集合，提交点是高水位不是固定尾节点，但「未达提交点不可读」同族。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[l("领导者切换：新 leader 在 ISR 内，已提交偏移应在。未进 ISR 的落后副本若被误拉成 leader 会丢——故控制器只从 ISR 选。这是"),e("a",{href:"/cs/leader-election-split-brain"},"脑裂"),l("在日志上的投影。早期控制器依赖 ZK，KRaft 把元数据也变成 Raft 日志。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"数字实例：leader 已收到 offset=7，两个 follower 分别追到 7 和 5，则高水位停在 5——消费者最多读到 5。等落后者追平到 7，水位才涨上去，这条消息才算「提交」。若 leader 崩了，控制器只会从 ISR 里挑新 leader，已提交前缀不丢。")],-1)),(t(),i(d,null,{default:r(()=>[n(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%94%9F%E4%BA%A7%E8%80%85%E5%86%99%E5%85%A5%20offset%3D7%22%5D%20--%3E%20L%5B%22leader%20%E6%97%A5%E5%BF%97%E5%B7%B2%E8%BF%BD%E5%8A%A0%E5%88%B0%207%22%5D%0A%20%20L%20--%3E%20F1%5B%22follower%20A%20%E5%A4%8D%E5%88%B6%E5%88%B0%207%22%5D%0A%20%20L%20--%3E%20F2%5B%22follower%20B%20%E5%8F%AA%E8%BF%BD%E5%88%B0%205%22%5D%0A%20%20F1%20--%3E%20HW%5B%22%E9%AB%98%E6%B0%B4%E4%BD%8D%20%3D%205%EF%BC%9AISR%20%E5%85%A8%E5%91%98%E9%83%BD%E6%9C%89%22%5D%0A%20%20F2%20--%3E%20HW%0A%20%20HW%20--%3E%20C%5B%22%E6%B6%88%E8%B4%B9%E8%80%85%E6%9C%80%E5%A4%9A%E8%AF%BB%E5%88%B0%20offset%3D5%22%5D%0A%20%20L%20--%3E%7C%22leader%20%E5%B4%A9%E6%BA%83%22%7C%20NL%5B%22%E6%96%B0%20leader%20%E5%8F%AA%E4%BB%8E%20ISR%20%E9%80%89%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">常见误区：以为 Kafka 保留数据就能当审计库。若误把主题设成按 key 压缩（每个 key 只留最新值），历史事件会被悄悄删光——这对 changelog 合理，对事件溯源等于销毁审计记录。</span></p><p>本课不写 Streams DSL。也不把 WAL 单机日志当 Kafka。</p><p>压缩日志（log compaction）按键留最新值：对 changelog 有用，对事件溯源会删历史——选错策略等于丢审计。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列全部配置项。不引入 Pulsar 分层存储全文。后课默认：要分区内全序重放用日志；要全局线性一致对象仍用 etcd/RSM。发布订阅下一课把「多消费者独立游标」说成模式。</p><p>日志是存储，位移是消费。提交点在 ISR，不在消费者 ack。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分区只追加有序；跨分区无全序。</li><li>高水位/ISR 定义提交；消费者读提交前缀。</li><li>位移回退 ⇒ 至少一次；业务去重要幂等。</li><li>出处：Kreps, Narkhede and Rao, 2011；Kafka 复制设计。</li></ul>',8))])}const R=E(f,[["render",A]]);export{u as __pageData,R as default};
